-- CounterNest POS Phase 31.8: finished-product batches, sale allocation, recalls, and customer/receipt traceability.

create table if not exists public.finished_product_batches (
  id uuid primary key default gen_random_uuid(),
  batch_record_number bigint generated by default as identity,
  shop_id uuid not null references public.shops(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete restrict,
  production_batch_id uuid references public.production_batches(id) on delete set null,
  batch_code text not null,
  best_before_on date,
  produced_quantity numeric(12,3) not null check(produced_quantity>0),
  remaining_quantity numeric(12,3) not null check(remaining_quantity>=0 and remaining_quantity<=produced_quantity),
  unit_cost_snapshot numeric(12,2) not null default 0 check(unit_cost_snapshot>=0),
  status text not null default 'active' check(status in('active','recalled','depleted')),
  recall_reason text,
  produced_at timestamptz not null default now(),
  created_by uuid references auth.users(id) on delete restrict,
  updated_at timestamptz not null default now()
);

create unique index if not exists finished_product_batch_production_unique on public.finished_product_batches(production_batch_id) where production_batch_id is not null;
create index if not exists finished_product_batches_fefo_idx on public.finished_product_batches(shop_id,product_id,status,best_before_on,produced_at);

create table if not exists public.finished_product_batch_sale_allocations (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id) on delete cascade,
  finished_batch_id uuid not null references public.finished_product_batches(id) on delete restrict,
  sale_id uuid not null references public.sales(id) on delete restrict,
  sale_item_id uuid not null references public.sale_items(id) on delete restrict,
  quantity_allocated numeric(12,3) not null check(quantity_allocated>0),
  quantity_returned numeric(12,3) not null default 0 check(quantity_returned>=0 and quantity_returned<=quantity_allocated),
  allocated_at timestamptz not null default now(),
  unique(finished_batch_id,sale_item_id)
);

create index if not exists finished_batch_allocations_batch_idx on public.finished_product_batch_sale_allocations(finished_batch_id,allocated_at desc);
create index if not exists finished_batch_allocations_sale_idx on public.finished_product_batch_sale_allocations(sale_id,sale_item_id);

create table if not exists public.finished_product_batch_events (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id) on delete cascade,
  finished_batch_id uuid not null references public.finished_product_batches(id) on delete restrict,
  action text not null check(action in('created','details_updated','sold','returned','adjusted','recalled','disposed')),
  quantity numeric(12,3),
  details jsonb not null default '{}'::jsonb,
  performed_by uuid references auth.users(id) on delete restrict,
  created_at timestamptz not null default now()
);

create index if not exists finished_batch_events_batch_idx on public.finished_product_batch_events(finished_batch_id,created_at desc);

alter table public.finished_product_batches enable row level security;
alter table public.finished_product_batch_sale_allocations enable row level security;
alter table public.finished_product_batch_events enable row level security;
drop policy if exists finished_product_batches_admin_select on public.finished_product_batches;
create policy finished_product_batches_admin_select on public.finished_product_batches for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());
drop policy if exists finished_batch_allocations_admin_select on public.finished_product_batch_sale_allocations;
create policy finished_batch_allocations_admin_select on public.finished_product_batch_sale_allocations for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());
drop policy if exists finished_batch_events_admin_select on public.finished_product_batch_events;
create policy finished_batch_events_admin_select on public.finished_product_batch_events for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

-- Existing sellable product stock predates reliable batch allocation, so preserve it as an explicit opening/untracked batch.
insert into public.finished_product_batches(shop_id,product_id,batch_code,produced_quantity,remaining_quantity,unit_cost_snapshot,status,produced_at)
select p.shop_id,p.id,'OPENING-31.8-'||upper(left(p.id::text,8)),p.stock,p.stock,coalesce(p.cost_price,0),'active',now()
from public.products p where p.stock>0 and not exists(select 1 from public.finished_product_batches b where b.product_id=p.id);

insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details)
select b.shop_id,b.id,'created',b.produced_quantity,jsonb_build_object('source','Phase 31.8 opening-stock migration','traceability','untracked')
from public.finished_product_batches b where b.batch_code like 'OPENING-31.8-%' and not exists(select 1 from public.finished_product_batch_events e where e.finished_batch_id=b.id and e.action='created');

create or replace function public.create_finished_batch_from_production() returns trigger
language plpgsql security definer set search_path=public as $$
declare v_finished uuid;v_cost numeric;
begin
  if new.status='completed' and old.status is distinct from 'completed' and coalesce(new.actual_quantity,0)>0 then
    select coalesce(cost_price,0) into v_cost from public.products where id=new.product_id and shop_id=new.shop_id;
    insert into public.finished_product_batches(shop_id,product_id,production_batch_id,batch_code,produced_quantity,remaining_quantity,unit_cost_snapshot,status,produced_at,created_by)
    values(new.shop_id,new.product_id,new.id,'B-'||lpad(new.batch_number::text,6,'0'),new.actual_quantity,new.actual_quantity,v_cost,'active',coalesce(new.completed_at,now()),new.completed_by)
    on conflict(production_batch_id) where production_batch_id is not null do nothing returning id into v_finished;
    if v_finished is not null then
      insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
      values(new.shop_id,v_finished,'created',new.actual_quantity,jsonb_build_object('source','production completion','production_batch_id',new.id,'production_batch_number',new.batch_number),new.completed_by);
    end if;
  end if;
  return new;
end $$;

drop trigger if exists finished_batch_from_production_trigger on public.production_batches;
create trigger finished_batch_from_production_trigger after update on public.production_batches for each row execute function public.create_finished_batch_from_production();

create or replace function public.create_finished_batch_from_new_product() returns trigger
language plpgsql security definer set search_path=public as $$
declare v_batch uuid;
begin
  if new.stock>0 then
    insert into public.finished_product_batches(shop_id,product_id,batch_code,produced_quantity,remaining_quantity,unit_cost_snapshot,status,produced_at,created_by)
    values(new.shop_id,new.id,'INITIAL-'||upper(left(new.id::text,10)),new.stock,new.stock,coalesce(new.cost_price,0),'active',now(),auth.uid()) returning id into v_batch;
    insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
    values(new.shop_id,v_batch,'created',new.stock,jsonb_build_object('source','new product opening stock','traceability','untracked'),auth.uid());
  end if;
  return new;
end $$;

drop trigger if exists finished_batch_new_product_trigger on public.products;
create trigger finished_batch_new_product_trigger after insert on public.products for each row execute function public.create_finished_batch_from_new_product();

-- Keep batch balances aligned when stock is received or manually adjusted. Production and restocked returns have their own batch sources.
create or replace function public.maintain_finished_batches_from_adjustment() returns trigger
language plpgsql security definer set search_path=public as $$
declare v_batch public.finished_product_batches%rowtype;v_id uuid;v_needed numeric;v_take numeric;v_active numeric;
begin
  if new.delta>0 and coalesce(new.reason,'') not like 'Production batch B-% completed%' and coalesce(new.reason,'') not like 'Refund #%' and coalesce(new.reason,'') not like 'Void receipt #%' then
    insert into public.finished_product_batches(shop_id,product_id,batch_code,produced_quantity,remaining_quantity,unit_cost_snapshot,status,produced_at,created_by)
    select new.shop_id,new.product_id,'ADJ-'||upper(left(new.id::text,12)),new.delta,new.delta,coalesce(p.cost_price,0),'active',new.created_at,new.created_by from public.products p where p.id=new.product_id
    returning id into v_id;
    insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
    values(new.shop_id,v_id,'created',new.delta,jsonb_build_object('source','inventory adjustment','adjustment_id',new.id,'reason',new.reason,'traceability','untracked'),new.created_by);
  elsif new.delta<0 then
    v_needed:=-new.delta;
    for v_batch in select * from public.finished_product_batches b where b.shop_id=new.shop_id and b.product_id=new.product_id and b.status='active' and b.remaining_quantity>0 order by(b.best_before_on is null),b.best_before_on,b.produced_at,b.id for update loop
      exit when v_needed<=0;
      v_take:=least(v_needed,v_batch.remaining_quantity);
      update public.finished_product_batches set remaining_quantity=remaining_quantity-v_take,status=case when remaining_quantity-v_take<=0 then 'depleted' else status end,updated_at=now() where id=v_batch.id;
      insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
      values(new.shop_id,v_batch.id,'adjusted',v_take,jsonb_build_object('direction','decrease','adjustment_id',new.id,'reason',new.reason),new.created_by);
      v_needed:=v_needed-v_take;
    end loop;
    if v_needed>0 then raise exception 'Finished-product batch balances do not cover this stock reduction'; end if;
  elsif new.delta>0 and(coalesce(new.reason,'') like 'Refund #%' or coalesce(new.reason,'') like 'Void receipt #%') then
    select coalesce(sum(remaining_quantity),0) into v_active from public.finished_product_batches where shop_id=new.shop_id and product_id=new.product_id and status='active';
    update public.products set stock=v_active,updated_at=now() where id=new.product_id and shop_id=new.shop_id;
  end if;
  return new;
end $$;

drop trigger if exists maintain_finished_batches_adjustment_trigger on public.inventory_adjustments;
create trigger maintain_finished_batches_adjustment_trigger after insert on public.inventory_adjustments for each row execute function public.maintain_finished_batches_from_adjustment();

create or replace function public.allocate_finished_batches_to_sale_item() returns trigger
language plpgsql security definer set search_path=public as $$
declare v_needed numeric:=new.qty;v_take numeric;v_batch public.finished_product_batches%rowtype;
begin
  for v_batch in
    select * from public.finished_product_batches b where b.shop_id=new.shop_id and b.product_id=new.product_id and b.status='active' and b.remaining_quantity>0 and(b.best_before_on is null or b.best_before_on>=current_date)
    order by(b.best_before_on is null),b.best_before_on,b.produced_at,b.id for update
  loop
    exit when v_needed<=0;
    v_take:=least(v_needed,v_batch.remaining_quantity);
    update public.finished_product_batches set remaining_quantity=remaining_quantity-v_take,status=case when remaining_quantity-v_take<=0 then 'depleted' else status end,updated_at=now() where id=v_batch.id;
    insert into public.finished_product_batch_sale_allocations(shop_id,finished_batch_id,sale_id,sale_item_id,quantity_allocated)
    values(new.shop_id,v_batch.id,new.sale_id,new.id,v_take);
    insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
    values(new.shop_id,v_batch.id,'sold',v_take,jsonb_build_object('sale_id',new.sale_id,'sale_item_id',new.id),auth.uid());
    v_needed:=v_needed-v_take;
  end loop;
  if v_needed>0 then raise exception 'Insufficient usable non-expired finished-product batch stock for %',new.product_name; end if;
  return new;
end $$;

drop trigger if exists finished_batch_sale_allocation_trigger on public.sale_items;
create trigger finished_batch_sale_allocation_trigger after insert on public.sale_items for each row execute function public.allocate_finished_batches_to_sale_item();

create or replace function public.return_finished_batches_from_refund() returns trigger
language plpgsql security definer set search_path=public as $$
declare v_restock boolean;v_needed numeric:=new.qty;v_take numeric;v_allocation public.finished_product_batch_sale_allocations%rowtype;v_batch uuid;v_product public.sale_items.product_id%type;
begin
  select restocked into v_restock from public.sale_refunds where id=new.refund_id and shop_id=new.shop_id;
  if not coalesce(v_restock,false) then return new; end if;
  select product_id into v_product from public.sale_items where id=new.sale_item_id;
  if v_product is null then return new; end if;
  perform 1 from public.products where id=v_product and shop_id=new.shop_id for update;
  for v_allocation in select * from public.finished_product_batch_sale_allocations where shop_id=new.shop_id and sale_item_id=new.sale_item_id and quantity_allocated>quantity_returned order by allocated_at desc,id for update loop
    exit when v_needed<=0;
    v_take:=least(v_needed,v_allocation.quantity_allocated-v_allocation.quantity_returned);
    update public.finished_product_batch_sale_allocations set quantity_returned=quantity_returned+v_take where id=v_allocation.id;
    update public.finished_product_batches set remaining_quantity=remaining_quantity+v_take,status=case when status='depleted' then 'active' else status end,updated_at=now() where id=v_allocation.finished_batch_id;
    insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
    select new.shop_id,v_allocation.finished_batch_id,'returned',v_take,jsonb_build_object('refund_id',new.refund_id,'sale_id',new.sale_id,'sale_item_id',new.sale_item_id),r.processed_by from public.sale_refunds r where r.id=new.refund_id;
    v_needed:=v_needed-v_take;
  end loop;
  if v_needed>0 then
    insert into public.finished_product_batches(shop_id,product_id,batch_code,produced_quantity,remaining_quantity,unit_cost_snapshot,status,produced_at,created_by)
    select new.shop_id,v_product,'RETURN-'||upper(left(new.refund_id::text,10)),v_needed,v_needed,coalesce(p.cost_price,0),'active',now(),r.processed_by from public.products p join public.sale_refunds r on r.id=new.refund_id where p.id=v_product
    returning id into v_batch;
    if v_batch is not null then
      insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
      select new.shop_id,v_batch,'created',v_needed,jsonb_build_object('source','restocked historical sale without batch allocation','refund_id',new.refund_id,'traceability','untracked'),r.processed_by from public.sale_refunds r where r.id=new.refund_id;
    end if;
  end if;
  return new;
end $$;

drop trigger if exists finished_batch_refund_return_trigger on public.sale_refund_items;
create trigger finished_batch_refund_return_trigger after insert on public.sale_refund_items for each row execute function public.return_finished_batches_from_refund();

create or replace function public.complete_production_batch_with_trace(p_batch_id uuid,p_actual_quantity numeric,p_waste_quantity numeric,p_completion_note text,p_batch_code text,p_best_before_on date)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_result jsonb;v_finished public.finished_product_batches%rowtype;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if nullif(trim(p_batch_code),'') is null then raise exception 'Finished-product batch code is required'; end if;
  if p_best_before_on is not null and p_best_before_on<current_date then raise exception 'Best-before date cannot be in the past at completion'; end if;
  v_result:=public.complete_production_batch(p_batch_id,p_actual_quantity,p_waste_quantity,p_completion_note);
  select * into v_finished from public.finished_product_batches where production_batch_id=p_batch_id and shop_id=public.current_shop_id() for update;
  if v_finished.id is null then raise exception 'Finished-product traceability batch was not created'; end if;
  update public.finished_product_batches set batch_code=trim(p_batch_code),best_before_on=p_best_before_on,updated_at=now() where id=v_finished.id;
  insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,details,performed_by)
  values(v_finished.shop_id,v_finished.id,'details_updated',jsonb_build_object('batch_code',trim(p_batch_code),'best_before_on',p_best_before_on,'source','production completion'),auth.uid());
  return v_result||jsonb_build_object('finished_batch_id',v_finished.id,'batch_code',trim(p_batch_code),'best_before_on',p_best_before_on);
end $$;

create or replace function public.update_finished_product_batch(p_finished_batch_id uuid,p_batch_code text,p_best_before_on date) returns void
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_old public.finished_product_batches%rowtype;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if nullif(trim(p_batch_code),'') is null then raise exception 'Batch code is required'; end if;
  select * into v_old from public.finished_product_batches where id=p_finished_batch_id and shop_id=v_shop for update;
  if v_old.id is null then raise exception 'Finished-product batch not found'; end if;
  update public.finished_product_batches set batch_code=trim(p_batch_code),best_before_on=p_best_before_on,updated_at=now() where id=v_old.id;
  insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,details,performed_by)
  values(v_shop,v_old.id,'details_updated',jsonb_build_object('old_batch_code',v_old.batch_code,'batch_code',trim(p_batch_code),'old_best_before_on',v_old.best_before_on,'best_before_on',p_best_before_on),auth.uid());
end $$;

create or replace function public.recall_finished_product_batch(p_finished_batch_id uuid,p_reason text) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_batch public.finished_product_batches%rowtype;v_product uuid;v_sales integer;v_customers integer;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'A recall reason of at least 5 characters is required'; end if;
  select product_id into v_product from public.finished_product_batches where id=p_finished_batch_id and shop_id=v_shop;
  if v_product is null then raise exception 'Finished-product batch not found'; end if;
  perform 1 from public.products where id=v_product and shop_id=v_shop for update;
  select * into v_batch from public.finished_product_batches where id=p_finished_batch_id and shop_id=v_shop for update;
  if v_batch.status='recalled' then raise exception 'Finished-product batch is already recalled'; end if;
  update public.products set stock=greatest(0,stock-v_batch.remaining_quantity),updated_at=now() where id=v_batch.product_id and shop_id=v_shop;
  update public.finished_product_batches set status='recalled',recall_reason=trim(p_reason),updated_at=now() where id=v_batch.id;
  insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
  values(v_shop,v_batch.id,'recalled',v_batch.remaining_quantity,jsonb_build_object('reason',trim(p_reason),'quarantined_quantity',v_batch.remaining_quantity),auth.uid());
  select count(distinct a.sale_id),count(distinct s.customer_id) filter(where s.customer_id is not null) into v_sales,v_customers from public.finished_product_batch_sale_allocations a join public.sales s on s.id=a.sale_id where a.finished_batch_id=v_batch.id and a.quantity_allocated>a.quantity_returned;
  return jsonb_build_object('finished_batch_id',v_batch.id,'quarantined_quantity',v_batch.remaining_quantity,'affected_sales',v_sales,'identified_customers',v_customers);
end $$;

create or replace function public.dispose_finished_product_batch(p_finished_batch_id uuid,p_quantity numeric,p_note text) returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_batch public.finished_product_batches%rowtype;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  if p_quantity is null or p_quantity<=0 then raise exception 'Disposal quantity must be greater than zero'; end if;
  if length(trim(coalesce(p_note,'')))<3 then raise exception 'A disposal note of at least 3 characters is required'; end if;
  select * into v_batch from public.finished_product_batches where id=p_finished_batch_id and shop_id=v_shop for update;
  if v_batch.id is null or v_batch.status<>'recalled' then raise exception 'Recall the finished-product batch before disposal'; end if;
  if p_quantity>v_batch.remaining_quantity then raise exception 'Disposal exceeds quarantined batch quantity'; end if;
  update public.finished_product_batches set remaining_quantity=remaining_quantity-p_quantity,updated_at=now() where id=v_batch.id;
  insert into public.finished_product_batch_events(shop_id,finished_batch_id,action,quantity,details,performed_by)
  values(v_shop,v_batch.id,'disposed',p_quantity,jsonb_build_object('note',trim(p_note)),auth.uid());
  return jsonb_build_object('finished_batch_id',v_batch.id,'remaining_quarantined',v_batch.remaining_quantity-p_quantity,'estimated_cost',round(p_quantity*v_batch.unit_cost_snapshot,2));
end $$;

create or replace function public.get_finished_product_traceability(p_best_before_days integer default 30) returns jsonb
language plpgsql security definer stable set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_days integer:=greatest(1,least(coalesce(p_best_before_days,30),365));
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  return jsonb_build_object(
    'summary',(select jsonb_build_object(
      'active_batches',count(*) filter(where status='active' and remaining_quantity>0),
      'expiring_batches',count(*) filter(where status='active' and remaining_quantity>0 and best_before_on between current_date and current_date+v_days),
      'expired_batches',count(*) filter(where status='active' and remaining_quantity>0 and best_before_on<current_date),
      'recalled_batches',count(*) filter(where status='recalled'),
      'quarantined_units',coalesce(sum(remaining_quantity) filter(where status='recalled'),0),
      'untracked_batches',count(*) filter(where batch_code like 'OPENING-31.8-%' or batch_code like 'INITIAL-%' or batch_code like 'ADJ-%' or batch_code like 'RETURN-%'),
      'affected_sales',(select count(distinct a.sale_id) from public.finished_product_batch_sale_allocations a join public.finished_product_batches rb on rb.id=a.finished_batch_id where rb.shop_id=v_shop and rb.status='recalled' and a.quantity_allocated>a.quantity_returned)
    ) from public.finished_product_batches where shop_id=v_shop),
    'batches',(select coalesce(jsonb_agg(to_jsonb(x) order by x.sort_rank,x.best_before_on nulls last,x.product_name,x.batch_code),'[]'::jsonb) from(
      select b.id,b.batch_record_number,b.product_id,p.name product_name,b.production_batch_id,pb.batch_number production_batch_number,b.batch_code,b.best_before_on,b.produced_quantity,b.remaining_quantity,b.unit_cost_snapshot,b.status,b.recall_reason,b.produced_at,
        case when b.status='recalled' then 'recalled' when b.status='depleted' or(b.remaining_quantity=0 and b.status<>'recalled') then 'depleted' when b.best_before_on<current_date then 'expired' when b.best_before_on<=current_date+v_days then 'expiring' when b.batch_code like 'OPENING-31.8-%' or b.batch_code like 'INITIAL-%' or b.batch_code like 'ADJ-%' or b.batch_code like 'RETURN-%' then 'untracked' else 'active' end calculated_status,
        case when b.status='recalled' then 0 when b.best_before_on<current_date and b.remaining_quantity>0 then 1 when b.best_before_on<=current_date+v_days and b.remaining_quantity>0 then 2 when b.batch_code like 'OPENING-31.8-%' or b.batch_code like 'INITIAL-%' or b.batch_code like 'ADJ-%' or b.batch_code like 'RETURN-%' then 3 when b.status='active' then 4 else 5 end sort_rank,
        (select coalesce(jsonb_agg(jsonb_build_object('sale_id',a.sale_id,'sale_item_id',a.sale_item_id,'receipt_number',s.receipt_number,'sold_at',s.created_at,'sale_status',s.status,'quantity_allocated',a.quantity_allocated,'quantity_returned',a.quantity_returned,'customer_id',s.customer_id,'customer_name',coalesce(c.name,s.customer_name_snapshot,'Guest'),'customer_email',coalesce(c.email,s.customer_email_snapshot),'customer_phone',c.phone) order by s.created_at desc),'[]'::jsonb) from public.finished_product_batch_sale_allocations a join public.sales s on s.id=a.sale_id left join public.customers c on c.id=s.customer_id where a.finished_batch_id=b.id) sales
      from public.finished_product_batches b join public.products p on p.id=b.product_id left join public.production_batches pb on pb.id=b.production_batch_id where b.shop_id=v_shop
    )x),
    'recent_events',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from(select e.id,e.created_at,e.action,e.quantity,e.details,b.batch_code,p.name product_name,coalesce(sp.display_name,'System migration') performed_by_name from public.finished_product_batch_events e join public.finished_product_batches b on b.id=e.finished_batch_id join public.products p on p.id=b.product_id left join public.staff_profiles sp on sp.user_id=e.performed_by and sp.shop_id=e.shop_id where e.shop_id=v_shop order by e.created_at desc limit 100)x)
  );
end $$;

create or replace function public.export_supply_operations_backup() returns jsonb
language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  return jsonb_build_object(
    'schema_version','1.10.0','exported_at',now(),'shop_id',v_shop,
    'ingredient_purchase_orders',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_orders t where shop_id=v_shop),
    'ingredient_purchase_order_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_order_items t where shop_id=v_shop),
    'ingredient_purchase_order_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_order_events t where shop_id=v_shop),
    'ingredient_purchase_receipts',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_receipts t where shop_id=v_shop),
    'ingredient_purchase_receipt_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_purchase_receipt_items t where shop_id=v_shop),
    'inventory_waste_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.inventory_waste_events t where shop_id=v_shop),
    'ingredient_lots',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_lots t where shop_id=v_shop),
    'ingredient_lot_allocations',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_lot_allocations t where shop_id=v_shop),
    'ingredient_lot_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.ingredient_lot_events t where shop_id=v_shop),
    'finished_product_batches',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.finished_product_batches t where shop_id=v_shop),
    'finished_product_batch_sale_allocations',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.finished_product_batch_sale_allocations t where shop_id=v_shop),
    'finished_product_batch_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.finished_product_batch_events t where shop_id=v_shop)
  );
end $$;

-- Phase 31.8 acceptance adds finished-batch-to-product ledger consistency and recall/expiry warnings.
create or replace function public.run_phase31_operational_acceptance(p_notes text default null) returns jsonb
language plpgsql security definer set search_path=public as $$
declare
  v_shop uuid:=public.current_shop_id();v_admins integer;v_products integer;v_negative integer;v_empty_recipes integer;v_invalid_recipe_items integer;v_overdue_batches integer;v_uncosted integer;v_recent_backup boolean;v_invalid_orders integer;v_overdue_orders integer;v_lot_gaps integer;v_expired integer;v_recalled integer;v_finished_gaps integer;v_finished_expired integer;v_finished_recalled integer;v_checks jsonb;v_status text;v_id uuid;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required'; end if;
  select count(*) into v_admins from public.staff_profiles where shop_id=v_shop and active and role='admin';select count(*) into v_products from public.products where shop_id=v_shop and active;select count(*) into v_negative from public.ingredients where shop_id=v_shop and current_quantity<0;
  select count(*) into v_empty_recipes from public.product_recipes pr where pr.shop_id=v_shop and pr.active and not exists(select 1 from public.recipe_items ri where ri.recipe_id=pr.id);
  select count(*) into v_invalid_recipe_items from public.recipe_items ri join public.product_recipes pr on pr.id=ri.recipe_id join public.ingredients i on i.id=ri.ingredient_id where pr.shop_id=v_shop and(ri.shop_id<>v_shop or i.shop_id<>v_shop or not i.active);
  select count(*) into v_overdue_batches from public.production_batches where shop_id=v_shop and status='scheduled' and scheduled_date<current_date;select count(*) into v_uncosted from public.products where shop_id=v_shop and active and coalesce(cost_price,0)=0;select exists(select 1 from public.backup_exports where shop_id=v_shop and requested_at>=now()-interval '30 days') into v_recent_backup;
  select count(*) into v_invalid_orders from public.ingredient_purchase_orders po join public.suppliers s on s.id=po.supplier_id where po.shop_id=v_shop and po.status in('ordered','partially_received') and(not s.active or not exists(select 1 from public.ingredient_purchase_order_items i where i.order_id=po.id));select count(*) into v_overdue_orders from public.ingredient_purchase_orders where shop_id=v_shop and status in('ordered','partially_received') and expected_date<current_date;
  select count(*) into v_lot_gaps from public.ingredients i where i.shop_id=v_shop and abs(i.current_quantity-coalesce((select sum(l.remaining_quantity) from public.ingredient_lots l where l.ingredient_id=i.id),0))>0.001;
  select count(*) into v_expired from public.ingredient_lots where shop_id=v_shop and status='active' and remaining_quantity>0 and expires_on<current_date;select count(*) into v_recalled from public.ingredient_lots where shop_id=v_shop and status='recalled' and remaining_quantity>0;
  select count(*) into v_finished_gaps from public.products p where p.shop_id=v_shop and abs(p.stock-coalesce((select sum(b.remaining_quantity) from public.finished_product_batches b where b.product_id=p.id and b.status='active'),0))>0.001;
  select count(*) into v_finished_expired from public.finished_product_batches where shop_id=v_shop and status='active' and remaining_quantity>0 and best_before_on<current_date;select count(*) into v_finished_recalled from public.finished_product_batches where shop_id=v_shop and status='recalled';
  v_checks:=jsonb_build_array(
    jsonb_build_object('id','active_admin','label','At least one active administrator','status',case when v_admins>0 then 'pass' else 'fail' end,'required',true,'detail',v_admins||' active administrator(s)'),jsonb_build_object('id','active_products','label','Active product catalog','status',case when v_products>0 then 'pass' else 'fail' end,'required',true,'detail',v_products||' active product(s)'),jsonb_build_object('id','ingredient_balances','label','No negative ingredient balances','status',case when v_negative=0 then 'pass' else 'fail' end,'required',true,'detail',v_negative||' invalid balance(s)'),jsonb_build_object('id','recipe_items','label','Active recipes contain ingredients','status',case when v_empty_recipes=0 then 'pass' else 'fail' end,'required',true,'detail',v_empty_recipes||' empty active recipe(s)'),jsonb_build_object('id','recipe_scope','label','Recipe ingredients are active and shop-scoped','status',case when v_invalid_recipe_items=0 then 'pass' else 'fail' end,'required',true,'detail',v_invalid_recipe_items||' invalid recipe line(s)'),jsonb_build_object('id','supply_orders','label','Open ingredient orders have active suppliers and lines','status',case when v_invalid_orders=0 then 'pass' else 'fail' end,'required',true,'detail',v_invalid_orders||' invalid open order(s)'),jsonb_build_object('id','lot_ledger','label','Ingredient lot totals match inventory balances','status',case when v_lot_gaps=0 then 'pass' else 'fail' end,'required',true,'detail',v_lot_gaps||' ingredient lot mismatch(es)'),jsonb_build_object('id','finished_batch_ledger','label','Active finished-batch totals match sellable product stock','status',case when v_finished_gaps=0 then 'pass' else 'fail' end,'required',true,'detail',v_finished_gaps||' finished-product batch mismatch(es)'),jsonb_build_object('id','recent_backup','label','Verified backup created in the last 30 days','status',case when v_recent_backup then 'pass' else 'fail' end,'required',true,'detail',case when v_recent_backup then 'Recent backup record found' else 'Create and verify a fresh backup' end),jsonb_build_object('id','expired_lots','label','No expired ingredient stock remains available','status',case when v_expired=0 then 'pass' else 'warning' end,'required',false,'detail',v_expired||' expired ingredient lot(s) require disposal'),jsonb_build_object('id','recalled_lots','label','No recalled ingredient stock remains available','status',case when v_recalled=0 then 'pass' else 'warning' end,'required',false,'detail',v_recalled||' recalled ingredient lot(s) require disposition'),jsonb_build_object('id','expired_finished_batches','label','No expired finished-product batch stock remains available','status',case when v_finished_expired=0 then 'pass' else 'warning' end,'required',false,'detail',v_finished_expired||' expired finished batch(es) require recall review'),jsonb_build_object('id','recalled_finished_batches','label','Finished-product recalls have been reviewed','status',case when v_finished_recalled=0 then 'pass' else 'warning' end,'required',false,'detail',v_finished_recalled||' recalled finished batch(es) remain in trace history'),jsonb_build_object('id','overdue_batches','label','No overdue scheduled production','status',case when v_overdue_batches=0 then 'pass' else 'warning' end,'required',false,'detail',v_overdue_batches||' overdue batch(es)'),jsonb_build_object('id','overdue_supply','label','No overdue ingredient deliveries','status',case when v_overdue_orders=0 then 'pass' else 'warning' end,'required',false,'detail',v_overdue_orders||' overdue ingredient order(s)'),jsonb_build_object('id','product_costs','label','Active products have a unit cost','status',case when v_uncosted=0 then 'pass' else 'warning' end,'required',false,'detail',v_uncosted||' uncosted product(s)')
  );
  v_status:=case when v_admins=0 or v_products=0 or v_negative>0 or v_empty_recipes>0 or v_invalid_recipe_items>0 or v_invalid_orders>0 or v_lot_gaps>0 or v_finished_gaps>0 or not v_recent_backup then 'failed' when v_expired>0 or v_recalled>0 or v_finished_expired>0 or v_finished_recalled>0 or v_overdue_batches>0 or v_overdue_orders>0 or v_uncosted>0 then 'warning' else 'passed' end;
  insert into public.operational_acceptance_runs(shop_id,release_version,phase,status,checks,notes,run_by) values(v_shop,'1.10.0','31.8',v_status,v_checks,nullif(trim(p_notes),''),auth.uid()) returning id into v_id;
  return jsonb_build_object('id',v_id,'release_version','1.10.0','phase','31.8','status',v_status,'checks',v_checks,'notes',nullif(trim(p_notes),''),'run_at',now());
end $$;

revoke all on function public.complete_production_batch_with_trace(uuid,numeric,numeric,text,text,date) from public;
revoke all on function public.update_finished_product_batch(uuid,text,date) from public;
revoke all on function public.recall_finished_product_batch(uuid,text) from public;
revoke all on function public.dispose_finished_product_batch(uuid,numeric,text) from public;
revoke all on function public.get_finished_product_traceability(integer) from public;
revoke all on function public.export_supply_operations_backup() from public;
revoke all on function public.run_phase31_operational_acceptance(text) from public;
grant execute on function public.complete_production_batch_with_trace(uuid,numeric,numeric,text,text,date) to authenticated;
grant execute on function public.update_finished_product_batch(uuid,text,date) to authenticated;
grant execute on function public.recall_finished_product_batch(uuid,text) to authenticated;
grant execute on function public.dispose_finished_product_batch(uuid,numeric,text) to authenticated;
grant execute on function public.get_finished_product_traceability(integer) to authenticated;
grant execute on function public.export_supply_operations_backup() to authenticated;
grant execute on function public.run_phase31_operational_acceptance(text) to authenticated;
